// [2026-09-22][Antigravity] Unit tests for parsing Activity Events exported by MigrationTool with ActivityEventExcelService
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using ClosedXML.Excel;
using TU.ACAMP.WebApp.Services.Activity;
using Xunit;

namespace TU.ACAMP.Tests;

public class ActivityEventImportTests
{
    [Fact]
    public async Task ParseImportExcelAsync_ParsesMigrationToolExportedEventFormatSuccessfully()
    {
        // 1. Arrange: Create an Excel in memory with the exact format generated by MigrationTool
        using var workbook = new XLWorkbook();
        var worksheet = workbook.Worksheets.Add("Activity Events");

        string unitTitle = "kWh";
        string qtyHeader = $"Quantity* ({unitTitle})";
        string[] headers = new[] { "Remark", "Time (yyyy-MM)*", qtyHeader };

        var headerBg = XLColor.FromHtml("#059669");
        var headerFg = XLColor.White;

        for (int c = 0; c < headers.Length; c++)
        {
            var cell = worksheet.Cell(1, c + 1);
            cell.Value = headers[c];
            cell.Style.Font.Bold = true;
            cell.Style.Font.FontColor = headerFg;
            cell.Style.Fill.BackgroundColor = headerBg;
            cell.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            cell.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
        }

        // Add 3 sample monthly rows
        worksheet.Cell(2, 1).Value = "Main Meter Facility A";
        worksheet.Cell(2, 2).Value = "2024-01";
        worksheet.Cell(2, 3).Value = 1250.50;

        worksheet.Cell(3, 1).Value = "Main Meter Facility A";
        worksheet.Cell(3, 2).Value = "2024-02";
        worksheet.Cell(3, 3).Value = 1180.75;

        worksheet.Cell(4, 1).Value = "Main Meter Facility A";
        worksheet.Cell(4, 2).Value = "2024-03";
        worksheet.Cell(4, 3).Value = 1320.00;

        using var ms = new MemoryStream();
        workbook.SaveAs(ms);
        ms.Position = 0;

        // 2. Act: Parse using V20 ActivityEventExcelService
        var service = new ActivityEventExcelService();
        var result = await service.ParseImportExcelAsync(ms);

        // 3. Assert
        Assert.NotNull(result);
        Assert.Equal(3, result.Count);

        // Verify Row 1
        Assert.Equal("Main Meter Facility A", result[0].Remark);
        Assert.Equal("2024-01", result[0].PeriodText);
        Assert.Equal(1250.50m, result[0].Quantity);
        Assert.Equal(eEventImportState.Ready, result[0].ImportState);
        Assert.True(result[0].IsValid);

        // Verify Row 2
        Assert.Equal("Main Meter Facility A", result[1].Remark);
        Assert.Equal("2024-02", result[1].PeriodText);
        Assert.Equal(1180.75m, result[1].Quantity);
        Assert.Equal(eEventImportState.Ready, result[1].ImportState);
        Assert.True(result[1].IsValid);

        // Verify Row 3
        Assert.Equal("Main Meter Facility A", result[2].Remark);
        Assert.Equal("2024-03", result[2].PeriodText);
        Assert.Equal(1320.00m, result[2].Quantity);
        Assert.Equal(eEventImportState.Ready, result[2].ImportState);
        Assert.True(result[2].IsValid);
    }

    [Fact]
    public async Task ParseImportExcelAsync_ParsesUnformattedQuantityHeaderSuccessfully()
    {
        // 1. Arrange: Create an Excel with simple "Quantity*" header
        using var workbook = new XLWorkbook();
        var worksheet = workbook.Worksheets.Add("Activity Events");

        string[] headers = new[] { "Remark", "Time (yyyy-MM)*", "Quantity*" };
        for (int c = 0; c < headers.Length; c++)
        {
            worksheet.Cell(1, c + 1).Value = headers[c];
        }

        worksheet.Cell(2, 1).Value = "Diesel Generator #1";
        worksheet.Cell(2, 2).Value = "2024-06";
        worksheet.Cell(2, 3).Value = 540.25;

        using var ms = new MemoryStream();
        workbook.SaveAs(ms);
        ms.Position = 0;

        // 2. Act
        var service = new ActivityEventExcelService();
        var result = await service.ParseImportExcelAsync(ms);

        // 3. Assert
        Assert.NotNull(result);
        Assert.Single(result);
        Assert.Equal("Diesel Generator #1", result[0].Remark);
        Assert.Equal("2024-06", result[0].PeriodText);
        Assert.Equal(540.25m, result[0].Quantity);
        Assert.Equal(eEventImportState.Ready, result[0].ImportState);
        Assert.True(result[0].IsValid);
    }

    [Fact]
    public async Task ParseImportExcelAsync_ParsesActualExportedTopicFileFromDiskIfPresent()
    {
        // 1. Arrange: Find any exported event file from output directory
        string baseDir = AppContext.BaseDirectory;
        var solutionDir = Directory.GetParent(baseDir)?.Parent?.Parent?.Parent?.Parent?.FullName;
        if (solutionDir == null) return;

        var outputDir = ResolveMigrationOutputDir(solutionDir); // [2026-09-23][Claude] follow MigrationTool OutputBasePath
        if (!Directory.Exists(outputDir)) return;

        var sampleFile = Directory.GetFiles(outputDir, "*.xlsx", SearchOption.AllDirectories)
            .FirstOrDefault(f => f.Contains(Path.DirectorySeparatorChar + "events" + Path.DirectorySeparatorChar));

        if (sampleFile == null || !File.Exists(sampleFile)) return;

        // 2. Act
        using var stream = File.OpenRead(sampleFile);
        var service = new ActivityEventExcelService();
        var result = await service.ParseImportExcelAsync(stream);

        // 3. Assert
        Assert.NotNull(result);
        Assert.NotEmpty(result);
        foreach (var item in result)
        {
            Assert.True(item.IsValid, $"Expected row {item.RowNumber} to be valid, but got errors: {string.Join(", ", item.ValidationErrors)}");
            Assert.Equal(eEventImportState.Ready, item.ImportState);
            Assert.NotNull(item.TimeStamp);
            Assert.True(item.Quantity >= 0);
        }

        // Validate OpenXml schema compliance
        using var doc = DocumentFormat.OpenXml.Packaging.SpreadsheetDocument.Open(sampleFile, false);
        var validator = new DocumentFormat.OpenXml.Validation.OpenXmlValidator();
        var errors = validator.Validate(doc).ToList();
        Assert.Empty(errors);
    }

    // [2026-09-23][Claude] Resolve export folder from MigrationTool/appsettings.json (MigrationSettings:OutputBasePath)
    // rooted path (e.g. D:\temp\output) is used as-is, relative path falls back to {solutionDir}/{path}
    private static string ResolveMigrationOutputDir(string solutionDir)
    {
        string configured = "output";
        var settingsPath = Path.Combine(solutionDir, "MigrationTool", "appsettings.json");
        if (File.Exists(settingsPath))
        {
            using var json = System.Text.Json.JsonDocument.Parse(File.ReadAllText(settingsPath));
            if (json.RootElement.TryGetProperty("MigrationSettings", out var ms) &&
                ms.TryGetProperty("OutputBasePath", out var obp) &&
                !string.IsNullOrWhiteSpace(obp.GetString()))
            {
                configured = obp.GetString()!;
            }
        }
        return Path.IsPathRooted(configured) ? configured : Path.Combine(solutionDir, configured);
    }

    private readonly Xunit.Abstractions.ITestOutputHelper _output;

    public ActivityEventImportTests(Xunit.Abstractions.ITestOutputHelper output)
    {
        _output = output;
    }

    [Fact]
    public void CheckAllExportedEventFiles_PathLengthAndValidity()
    {
        string baseDir = AppContext.BaseDirectory;
        var solutionDir = Directory.GetParent(baseDir)?.Parent?.Parent?.Parent?.Parent?.FullName;
        Assert.NotNull(solutionDir);

        var outputDir = ResolveMigrationOutputDir(solutionDir); // [2026-09-23][Claude] follow MigrationTool OutputBasePath
        _output.WriteLine($"Checking outputDir: {outputDir}");
        Assert.True(Directory.Exists(outputDir), $"Output directory does not exist: {outputDir}");

        var allEventFiles = Directory.GetFiles(outputDir, "*.xlsx", SearchOption.AllDirectories)
            .Where(f => f.Contains(Path.DirectorySeparatorChar + "events" + Path.DirectorySeparatorChar))
            .ToList();

        _output.WriteLine($"Found {allEventFiles.Count} event files.");
        Assert.NotEmpty(allEventFiles);

        int longPathCount = 0;
        var validator = new DocumentFormat.OpenXml.Validation.OpenXmlValidator();

        int duplicateMonthCount = 0;
        foreach (var file in allEventFiles)
        {
            if (file.Length > 218)
            {
                longPathCount++;
                _output.WriteLine($"[LONG PATH: {file.Length} chars] {file}");
            }

            // Test if file can be opened and is valid OpenXML
            using var doc = DocumentFormat.OpenXml.Packaging.SpreadsheetDocument.Open(file, false);
            var errors = validator.Validate(doc).ToList();
            if (errors.Any())
            {
                _output.WriteLine($"[VALIDATION ERROR in {Path.GetFileName(file)}]: {string.Join("; ", errors.Select(e => e.Description))}");
                throw new Exception($"Validation failed for {file}: {string.Join("; ", errors.Select(e => e.Description))}");
            }

            // Check if there are duplicate periods in the file
            using var stream = File.OpenRead(file);
            using var wb = new ClosedXML.Excel.XLWorkbook(stream);
            var ws = wb.Worksheet(1);
            var seen = new HashSet<string>();
            foreach (var row in ws.RowsUsed().Skip(1))
            {
                var period = row.Cell(2).GetString().Trim();
                if (seen.Contains(period))
                {
                    duplicateMonthCount++;
                    _output.WriteLine($"[DUPLICATE MONTH in {Path.GetFileName(file)}]: {period} at row {row.RowNumber()}");
                }
                seen.Add(period);
            }
        }

        _output.WriteLine($"Total event files checked: {allEventFiles.Count}, Long paths (>218): {longPathCount}, Duplicate months: {duplicateMonthCount}");
        Assert.True(longPathCount == 0, $"Found {longPathCount} files with path length > 218 characters out of {allEventFiles.Count} files!");
        Assert.True(duplicateMonthCount == 0, $"Found {duplicateMonthCount} duplicate month rows across event files!");
    }
}
